const { fonte, janela } = $json;
const versaoApi = 'v3';
const LINHAS_POR_PAGINA = 25000;
const URL_DA_CONSULTA = `https://www.googleapis.com/webmasters/${versaoApi}/sites/${encodeURIComponent(fonte.externalId)}/searchAnalytics/query`;

const METRICAS_ANTIGAS = ['clicks', 'impressions', 'ctr', 'position'];
const METRICAS = ['cliques', 'impressoes', 'ctr', 'posicao_media'];

const RECORTES = {
  padrao: { opcional: false, dimensoes: [['date', 'metricDate'], ['device', 'device']], metricas: METRICAS_ANTIGAS },
  consulta_pagina: { opcional: false, dimensoes: [['date', 'metricDate'], ['query', 'consulta'], ['page', 'pagina']], metricas: METRICAS },
  pagina: { opcional: false, dimensoes: [['date', 'metricDate'], ['page', 'pagina']], metricas: METRICAS },
  pais_dispositivo: { opcional: false, dimensoes: [['date', 'metricDate'], ['country', 'pais'], ['device', 'dispositivo']], metricas: METRICAS },
  aparencia: { opcional: true, porDia: true, dimensoes: [['searchAppearance', 'aparencia']], metricas: METRICAS },
  tipo: { opcional: false, porTipo: true, descartaSemImpressao: true, dimensoes: [['date', 'metricDate']], metricas: METRICAS },
};

const TIPOS_DE_BUSCA = ['image', 'video', 'news', 'discover', 'googleNews'];

const DIA_MS = 86_400_000;
const diasDaJanela = Array.from(
  { length: Math.round((Date.parse(janela.end) - Date.parse(janela.start)) / DIA_MS) + 1 },
  (_, indice) => new Date(Date.parse(janela.start) + indice * DIA_MS).toISOString().slice(0, 10),
);

const consultas = Object.fromEntries(Object.entries(RECORTES).map(([tabela, recorte]) => [tabela, {
  tabela,
  ...recorte,
  ...(recorte.porDia ? { dias: diasDaJanela } : {}),
  ...(recorte.porTipo ? { tipos: TIPOS_DE_BUSCA } : {}),
  corpo: {
    startDate: janela.start,
    endDate: janela.end,
    dimensions: recorte.dimensoes.map(([nome]) => nome),
    rowLimit: LINHAS_POR_PAGINA,
    startRow: 0,
    dataState: 'final',
  },
}]));

return [{ json: { inicio: Date.now(), versaoApi, fonte, url: URL_DA_CONSULTA, consultas } }];

const contexto = $('Montar requisição').first().json;
const TABELAS = ["padrao","consulta_pagina","pagina","pais_dispositivo","aparencia","tipo"];
const coletadas = TABELAS.map((tabela) => ({
  consulta: contexto.consultas[tabela],
  respostas: $(`Fechar ${tabela}`).first().json.respostas,
}));
const respostas = coletadas.flatMap((item) => item.respostas);
const requests = respostas.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const CONFIGURACAO_DO_PROJETO = /SERVICE_DISABLED|accessNotConfigured|has not been used in project/;
const SINAIS_DE_LIMITE = /RESOURCE_EXHAUSTED|RATE_LIMIT|rateLimitExceeded|userRateLimitExceeded|quotaExceeded|dailyLimitExceeded|Quota exceeded|Exhausted|Too many requests/i;
const SINAIS_DE_COTA_DIARIA = /dailyLimitExceeded|quotaExceeded|per day|PerDay|daily|Number of operations/i;
const ESCOPO_INSUFICIENTE = /ACCESS_TOKEN_SCOPE_INSUFFICIENT|insufficient authentication scopes/i;
const PERMISSAO_NEGADA = /PERMISSION_DENIED|caller does not have permission|does not have (sufficient )?permission|insufficientPermissions/i;
function semPermissaoNoRecurso(statusCode, texto) {
  return statusCode === 403 && PERMISSAO_NEGADA.test(texto) && !ESCOPO_INSUFICIENTE.test(texto) && !/DEVELOPER_TOKEN/.test(texto);
}
function mensagemSemAcesso() {
  const alvo = typeof contexto === 'undefined' ? '' : String(contexto?.fonte?.externalId ?? '').split('locations/').pop();
  return `Sem permissão no site ${alvo} — a conta autorizada não acessa este site`.replace('  ', ' ').slice(0, 500);
}
function falhaDaRecusa(statusCode, erro, detalhe) {
  const texto = JSON.stringify(erro ?? {});
  if (CONFIGURACAO_DO_PROJETO.test(texto)) return { causa: 'api_recusou', detalhe };
  if (statusCode === 429 || SINAIS_DE_LIMITE.test(texto)) {
    return { causa: 'limite_de_uso', detalhe: String(detalhe).slice(0, 500), pausa: SINAIS_DE_COTA_DIARIA.test(texto) ? 'cota_diaria' : 'limite_temporario', minutos: null };
  }
  if (/DEVELOPER_TOKEN/.test(texto)) return { causa: 'api_recusou', detalhe };
  if (semPermissaoNoRecurso(statusCode, texto)) return { causa: 'sem_acesso', detalhe: mensagemSemAcesso() };
  if (statusCode === 401 || statusCode === 403) return { causa: 'reauth_pending', detalhe };
  return { causa: 'api_recusou', detalhe };
}


const falhaDeRede = respostas.find((resposta) => resposta.error);
if (falhaDeRede) {
  const detalhe = falhaDeRede.error?.message ?? String(falhaDeRede.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

const aceita = (consulta, resposta) => resposta.statusCode >= 200 && resposta.statusCode < 300 || (consulta.opcional && resposta.statusCode === 400);
const recusada = coletadas.flatMap((item) => item.respostas.map((resposta) => ({ consulta: item.consulta, resposta }))).find((par) => !aceita(par.consulta, par.resposta))?.resposta;
if (recusada) {
  const erro = Array.isArray(recusada.body) ? recusada.body[0]?.error : recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  return devolver([], [falhaDaRecusa(recusada.statusCode, erro, detalhe)]);
}

const motivoDaRecusa = (resposta) => {
  if (resposta?.error) return `falha de rede: ${resposta.error?.message ?? String(resposta.error)}`;
  const erro = Array.isArray(resposta?.body) ? resposta.body[0]?.error : resposta?.body?.error;
  return String(erro?.message || `HTTP ${resposta?.statusCode}`);
};

function coletaIncompleta(recusas) {
  const porTabela = new Map();
  for (const { tabela, resposta } of recusas) {
    const atual = porTabela.get(tabela) ?? { total: 0, motivo: motivoDaRecusa(resposta) };
    porTabela.set(tabela, { ...atual, total: atual.total + 1 });
  }
  return [...porTabela].map(([tabela, { total, motivo }]) => ({
    causa: 'coleta_incompleta',
    detalhe: `${tabela}: ${total > 1 ? `${total} pedidos recusados, ` : ''}${motivo}`.slice(0, 500),
  }));
}

const incompletas = coletaIncompleta(coletadas.flatMap(({ consulta, respostas: paginas }) => paginas
  .filter((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300))
  .map((resposta) => ({ tabela: consulta.tabela, resposta }))));

const LIMITE_DE_PAGINAS = 80;
for (const { consulta, respostas: paginas } of coletadas) {
  const porGrupo = new Map();
  for (const resposta of paginas) porGrupo.set(resposta.dia ?? resposta.tipo ?? '', [...(porGrupo.get(resposta.dia ?? resposta.tipo ?? '') ?? []), resposta]);
  const truncado = [...porGrupo.values()].some((grupo) => grupo.length >= LIMITE_DE_PAGINAS && (grupo[grupo.length - 1].body?.rows?.length ?? 0) >= consulta.corpo.rowLimit);
  const cheia = consulta.porTipo && paginas.some((resposta) => (resposta.body?.rows?.length ?? 0) >= consulta.corpo.rowLimit);
  if (truncado || cheia) incompletas.push({ causa: 'coleta_incompleta', detalhe: `${consulta.tabela}: paginação interrompida no limite de requisições` });
}

const semConsultaNemAncora = (endereco) => (typeof endereco === 'string' ? endereco.split(/[?#]/)[0] : endereco);

function agruparPorPagina(consulta, saidas) {
  if (!consulta.dimensoes.some(([, campo]) => campo === 'pagina')) return saidas;
  const [cliques, impressoes, ctr, posicao] = consulta.metricas;
  const grupos = new Map();
  for (const saida of saidas) {
    const chave = JSON.stringify([saida.metricDate ?? null, ...consulta.dimensoes.map(([, campo]) => saida[campo])]);
    const atual = grupos.get(chave);
    if (!atual) {
      grupos.set(chave, { ...saida, somaDaPosicao: saida[posicao] * saida[impressoes] });
      continue;
    }
    atual[cliques] += saida[cliques];
    atual[impressoes] += saida[impressoes];
    atual.somaDaPosicao += saida[posicao] * saida[impressoes];
  }
  return [...grupos.values()].map(({ somaDaPosicao, ...grupo }) => ({
    ...grupo,
    [ctr]: grupo[impressoes] > 0 ? grupo[cliques] / grupo[impressoes] : 0,
    [posicao]: grupo[impressoes] > 0 ? somaDaPosicao / grupo[impressoes] : grupo[posicao],
  }));
}

const linhas = coletadas.flatMap(({ consulta, respostas: paginas }) => agruparPorPagina(consulta, paginas
  .filter((resposta) => resposta.statusCode >= 200 && resposta.statusCode < 300)
  .flatMap((resposta) => (resposta.body?.rows ?? []).map((linha) => ({ linha, dia: resposta.dia, tipo: resposta.tipo })))
  .filter(({ linha }) => !consulta.descartaSemImpressao || Number(linha.impressions ?? 0) > 0)
  .map(({ linha, dia, tipo }) => {
    const saida = consulta.tabela === 'padrao' ? {} : { _tabela: consulta.tabela };
    if (consulta.porDia) saida.metricDate = dia ?? null;
    if (consulta.porTipo) saida.tipo = tipo ?? null;
    consulta.dimensoes.forEach(([, campo], indice) => {
      saida[campo] = campo === 'pagina' ? semConsultaNemAncora(linha.keys?.[indice]) ?? null : linha.keys?.[indice] ?? null;
    });
    saida[consulta.metricas[0]] = Number(linha.clicks ?? 0);
    saida[consulta.metricas[1]] = Number(linha.impressions ?? 0);
    saida[consulta.metricas[2]] = Number(linha.ctr ?? 0);
    saida[consulta.metricas[3]] = Number(linha.position ?? 0);
    return saida;
  })));

if (linhas.length === 0) return devolver([], incompletas.length > 0 ? incompletas : [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas.map((linha) => ({ ...linha, versaoApi: contexto.versaoApi })), incompletas);
